package com.example.proyectolp.service;
import com.example.proyectolp.repository.UserBadgeRepository;import java.util.*;
public class BadgeService {public static final Map<String,String> CATALOG=Map.of("PRIMERA_TAREA","Primera tarea","PRIMER_HABITO","Primer hábito","RACHA_7","Racha de 7 días","RACHA_30","Racha de 30 días","NIVEL_5","Nivel 5","PRIMER_PROYECTO","Primer proyecto","PRIMERA_META","Primera meta","CREDITOS_50","50 créditos ganados");private final UserBadgeRepository repo;public BadgeService(SupabaseService db){repo=new UserBadgeRepository(db);}public List<String> unlock(String... codes)throws Exception{List<String> out=new ArrayList<>();for(String c:codes)if(CATALOG.containsKey(c)&&repo.unlock(c))out.add(c);return out;}public Set<String> unlocked()throws Exception{return repo.list();}}
